import{_ as a,c as e,a as t,aS as o}from"./chunks/framework.BB9D2qGO.js";const k=JSON.parse('{"title":"分布式","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/mianshi/分布式.md","filePath":"note/back-end/mianshi/分布式.md","lastUpdated":1756895529000}'),r={name:"note/back-end/mianshi/分布式.md"},i=o('<h1 id="分布式" tabindex="-1">分布式 <a class="header-anchor" href="#分布式" aria-label="Permalink to &quot;分布式&quot;">​</a></h1><h2 id="cap" tabindex="-1">CAP <a class="header-anchor" href="#cap" aria-label="Permalink to &quot;CAP&quot;">​</a></h2><p>分区容错性 是指分布式网络中部分网络不可用，但系统依然正常对外提供服务。</p><p>比如：北京的订单系统，访问上海的库存系统，可能导致失败。如果发生失败，就要在A和C之间做出选择。 要么停止系统进行错误恢复，要么继续服务但是降低一致性，所以说只能保证AP或CP。</p><p>所以，只要是分布式系统，因为网络故障是百分百存在的，所以P是必备的，剩下的就是AP还是CP了</p><h2 id="如何保证幂等" tabindex="-1">如何保证幂等 <a class="header-anchor" href="#如何保证幂等" aria-label="Permalink to &quot;如何保证幂等&quot;">​</a></h2><p>所谓幂等，其实就是说你这个操作，执行1次和多次返回的结果是一样的。</p><ol><li>用数据库唯一键实现</li><li>业务实现，执行前先查询是否存在或者状态字段来判断是否已经处理过了</li><li>颁发token，再加分布式锁，处理完之后删除token，下一个同样的请求就被拦截住了</li></ol><h2 id="分布式锁" tabindex="-1">分布式锁 <a class="header-anchor" href="#分布式锁" aria-label="Permalink to &quot;分布式锁&quot;">​</a></h2><p><strong>什么是分布式锁？</strong></p><p>在分布式环境下，多个线程需要操作同一份资源，只允许一个线程进行操作。</p><h3 id="数据库实现" tabindex="-1">数据库实现 <a class="header-anchor" href="#数据库实现" aria-label="Permalink to &quot;数据库实现&quot;">​</a></h3><p>可以基于数据库，新增一条数据，uk唯一键来实现，或者根据<code>for update</code>来实现，都可以。</p><blockquote><p>前提肯定是需要根据业务有一个唯一的key，也就是锁，然后新增成功就说明获取锁成功，业务执行完成之后就删掉即可。</p></blockquote><h3 id="redis实现" tabindex="-1">redis实现 <a class="header-anchor" href="#redis实现" aria-label="Permalink to &quot;redis实现&quot;">​</a></h3><p><code>setnx()</code>来实现， <code>setnx(lockkey, 当前时间+过期超时时间)，如果返回 1，则获取锁成功；如果返回 0 则没有获取到锁。</code></p>',16),n=[i];function d(c,l,s,h,p,_){return t(),e("div",null,n)}const m=a(r,[["render",d]]);export{k as __pageData,m as default};
